import { Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import axiosInstance from '../axiosConfig';

// REQ-3.1.3: Delete Tournament — Organizer can delete/cancel tournament.
const TournamentList = ({ tournaments, setTournaments, setEditingTournament }) => {
  const { user } = useAuth();

  const handleDelete = async (tournamentId) => {
    try {
      await axiosInstance.delete(`/api/tournaments/${tournamentId}`, {
        headers: { Authorization: `Bearer ${user.token}` },
      });
      setTournaments(tournaments.filter((t) => t._id !== tournamentId));
    } catch (error) {
      alert('Failed to delete tournament.');
    }
  };

  return (
    <div>
      {tournaments.map((t) => (
        <div key={t._id} className="bg-gray-100 p-4 mb-4 rounded shadow">
          <h2 className="font-bold">{t.name}</h2>
          <p className="text-sm text-gray-600">{t.sport}</p>
          <p>{t.description}</p>
          <p className="text-sm text-gray-500">
            Date: {new Date(t.date).toLocaleDateString()}
          </p>
          <p className="text-sm text-gray-500">
            Capacity: {t.participants.length}/{t.maxCapacity} &middot; Status: {t.status}
          </p>
          <div className="mt-2">
            <Link
              to={`/tournaments/${t._id}`}
              className="mr-2 bg-gray-500 text-white px-4 py-2 rounded inline-block"
            >
              View
            </Link>
            <Link
              to={`/tournaments/${t._id}/participants`}
              className="mr-2 bg-indigo-500 text-white px-4 py-2 rounded inline-block"
            >
              View Participants
            </Link>
            <button
              onClick={() => setEditingTournament(t)}
              className="mr-2 bg-yellow-500 text-white px-4 py-2 rounded"
            >
              Edit
            </button>
            <button
              onClick={() => handleDelete(t._id)}
              className="bg-red-500 text-white px-4 py-2 rounded"
            >
              Delete
            </button>
          </div>
        </div>
      ))}
    </div>
  );
};

export default TournamentList;
